# A 2D navigation-mesh generator for Godot 4.3 (pure GDScript, no assets).
# Computes the triangulation of a boundary polygon with holes, triangle
# adjacency, and centroid-based triangle-level pathfinding over AStar2D.


func _init() -> void:
	pass


## Rebuilds the navigation mesh.
## boundary: simple, non-self-intersecting, concave allowed, world-space.
## holes: Array of PackedVector2Array, each a simple polygon strictly inside
##        boundary, holes do not touch/overlap each other or the boundary.
func build(boundary: PackedVector2Array, holes: Array) -> void:
	print("build: build_combined...")
	_boundary = _to_ccw(boundary)
	_holes = []
	for hole in holes:
		_holes.append(_to_cw(PackedVector2Array(hole)))

	_build_combined()
	print("build: triangulate...")
	_indices = Geometry2D.triangulate_polygon(_verts)

	# Convert to explicit triangle array, dropping degenerate triangles.
	_triangles = []
	var n_tris: int = _indices.size() / 3
	for i in range(n_tris):
		var p0: Vector2 = _verts[_indices[i * 3 + 0]]
		var p1: Vector2 = _verts[_indices[i * 3 + 1]]
		var p2: Vector2 = _verts[_indices[i * 3 + 2]]
		if abs(_signed_area2(p0, p1, p2)) > 1e-9:
			_triangles.append(PackedVector2Array([p0, p1, p2]))

	print("build: triangles: ", _triangles.size())
	var n: int = _triangles.size()
	_adjacency = []
	_adjacency.resize(n)
	for i in range(n):
		_adjacency[i] = []
	_centroids = []
	_centroids.resize(n)
	for i in range(n):
		var t: PackedVector2Array = _triangles[i]
		var c: Vector2 = (t[0] + t[1] + t[2]) / 3.0
		_centroids[i] = c

	_centroid_to_indices = {}
	for i in range(n):
		var c: Vector2 = _centroids[i]
		var key: Vector2 = _snap(c)
		if not key in _centroid_to_indices:
			_centroid_to_indices[key] = []
		_centroid_to_indices[key].append(i)

	# Build adjacency by sharing edges (two matching vertices).
	var eps: float = 1e-5
	for i in range(n):
		for j in range(i + 1, n):
		if _are_adjacent(_triangles[i], _triangles[j], eps):
			_adjacency[i].append(j)
			_adjacency[j].append(i)
	for i in range(n):
		_adjacency[i].sort()

	# AStar graph: node = triangle index, position = centroid.
	_astar = AStar2D.new()
	for i in range(n):
		_astar.add_point(i, _centroids[i])
	for i in range(n):
		for neighbor in _adjacency[i]:
			_astar.connect_points(i, neighbor)


## Returns Array of PackedVector2Array, each triangle's three world vertices.
func get_triangles() -> Array:
	return _triangles


## Returns Array (indices) of each triangle's neighbors, sorted.
func get_adjacency() -> Array:
	return _adjacency


## Which triangle contains point? -1 if outside/hole.
func triangle_at_point(point: Vector2) -> int:
	if not _is_point_in_walkable(point):
		return -1
	print("build: triangles: ", _triangles.size())
	var n: int = _triangles.size()
	# First, try candidates with a centroid nearby (optimization).
	var snap: Vector2 = _snap(point)
	for key in _centroid_to_indices:
		if _approx_eq(key, snap, 1e-1):
			for i in _centroid_to_indices[key]:
			if _is_point_in_triangle(_triangles[i], point):
				return i
	# Fallback scan.
	for i in range(n):
		if _is_point_in_triangle(_triangles[i], point):
			return i
	return -1


## Centroid-based AStar path from start-triangle to end-triangle.
func find_triangle_path(from_point: Vector2, to_point: Vector2) -> PackedInt32Array:
	var start: int = triangle_at_point(from_point)
	var end: int = triangle_at_point(to_point)
	if start < 0 or end < 0:
		return PackedInt32Array()
	if start == end:
		var res: PackedInt32Array = PackedInt32Array()
		res.append(start)
		return res
	if not _astar.has_point(start) or not _astar.has_point(end):
		return PackedInt32Array()
	var path_verts: PackedVector2Array = _astar.get_point_path(start, end)
	if path_verts.is_empty():
		return PackedInt32Array()
	var path: PackedInt32Array = PackedInt32Array()
	var prev: int = -1
	for k in range(path_verts.size()):
		var v: Vector2 = path_verts[k]
		var snap: Vector2 = _snap(v)
		var candidates: Array = []
		if snap in _centroid_to_indices:
			candidates = _centroid_to_indices[snap]
		var best: int = -1
		if k == 0:
			for cand in candidates:
				if cand == start:
					best = cand
					break
			if best < 0 and not candidates.is_empty():
				best = candidates[0]
		else:
			for cand in candidates:
				if _adjacency[prev].has(cand):
					best = cand
					break
		if best < 0:
			return PackedInt32Array()
		path.append(best)
		prev = best
	return path

# --- Internal ---

var _boundary: PackedVector2Array
var _holes: Array
var _verts: PackedVector2Array
var _indices: PackedInt32Array
var _triangles: Array
var _adjacency: Array
var _centroids: Array
var _centroid_to_indices: Dictionary
var _astar: AStar2D

func _is_point_in_walkable(p: Vector2) -> bool:
	if not Geometry2D.is_point_in_polygon(p, _boundary):
		return false
	for hole in _holes:
		if Geometry2D.is_point_in_polygon(p, hole):
			return false
	return true

func _is_point_in_triangle(tri: PackedVector2Array, p: Vector2) -> bool:
	var a: Vector2 = tri[0]; var b: Vector2 = tri[1]; var c: Vector2 = tri[2]
	# Barycentric with epsilon.
	var eps: float = 1e-7
	var det: float = (b.y - c.y) * (a.x - c.x) + (c.x - b.x) * (a.y - c.y)
	if abs(det) < 1e-11:
		return false
	var u: float = ((b.y - c.y) * (p.x - c.x) + (c.x - b.x) * (p.y - c.y)) / det
	var v: float = ((c.y - a.y) * (p.x - c.x) + (a.x - c.x) * (p.y - c.y)) / det
	var w: float = 1.0 - u - v
	return u >= -eps and v >= -eps and w >= -eps

func _build_combined() -> void:
	_verts = PackedVector2Array()
	# boundary is already CCW.
	_verts.append_array(_boundary)

	# For each hole, pick a valid bridge to the boundary.
	for hole in _holes:
		_verts = _add_hole_with_bridge(_verts, hole)

func _add_hole_with_bridge(poly: PackedVector2Array, hole: PackedVector2Array) -> PackedVector2Array:
	var h_min_idx: int = -1
	var min_x: float = INF
	for i in range(hole.size()):
		if hole[i].x < min_x:
			min_x = hole[i].x
			h_min_idx = i
	var h_min: Vector2 = hole[h_min_idx]

	var sorted_b: Array = []
	for i in range(poly.size()):
		sorted_b.append({"idx": i, "pos": poly[i], "dist_sq": poly[i].distance_squared_to(h_min)})
	sorted_b.sort_custom(func(a, b): return a.dist_sq < b.dist_sq)

	var dirs: Array = [Vector2(-1, 0), Vector2(1, 0), Vector2(0, -1), Vector2(0, 1)]
	var found: bool = false
	var best_b_idx: int = -1
	var best_hit: Vector2 = Vector2()

	for sb in sorted_b:
		var b_i: int = sb.idx
		var b_pos: Vector2 = sb.pos
		# Segment from h_min to boundary point candidate.
		if _bridge_is_valid(poly, hole, h_min, b_pos):
			best_b_idx = b_i
			best_hit = b_pos
			found = true
			break

	if not found:
		best_b_idx = sorted_b[0].idx
		best_hit = sorted_b[0].pos

	var res: PackedVector2Array = PackedVector2Array()
	for i in range(poly.size()):
		res.append(poly[i])
		if i == best_b_idx:
			res.append(best_hit)
			res.append_array(_hole_rotated_for_bridge(hole, h_min_idx))
			res.append(best_hit)
	return res

func _bridge_is_valid(poly: PackedVector2Array, hole: PackedVector2Array, from_: Vector2, to: Vector2) -> bool:
	if from_.distance_squared_to(to) < 1e-9:
		return false
	# Doesn't intersect any hole boundary.
	for h in _holes:
		for i in range(h.size()):
			var u: Vector2 = h[i]; var v: Vector2 = h[(i + 1) % h.size()]
			if _seg_seg_intersects(from_, to, u, v):
				return false
	# Doesn't intersect boundary except at bridge endpoint.
	for i in range(poly.size()):
		var u: Vector2 = poly[i]; var v: Vector2 = poly[(i + 1) % poly.size()]
		if _seg_seg_intersects_exclusive(from_, to, u, v, to):
			return false
	# Midpoint inside walkable.
	var mid: Vector2 = from_ + 0.5 * (to - from_)
	if not Geometry2D.is_point_in_polygon(mid, _boundary):
		return false
	for h in _holes:
		if Geometry2D.is_point_in_polygon(mid, h):
			return false
	return true

func _seg_seg_intersects(a: Vector2, b: Vector2, c: Vector2, d: Vector2) -> bool:
	var ccw0: float = _ccw(a, b, c); var ccw1: float = _ccw(a, b, d)
	var ccw2: float = _ccw(c, d, a); var ccw3: float = _ccw(c, d, b)
	return ccw0 * ccw1 < -1e-11 and ccw2 * ccw3 < -1e-11

func _seg_seg_intersects_exclusive(a: Vector2, b: Vector2, c: Vector2, d: Vector2, excl: Vector2) -> bool:
	# Same but ignores intersection occurring exactly at excl.
	if _are_close(c, excl) or _are_close(d, excl):
		# Ignore the endpoint at excl, but must check if the OTHER endpoint
		# intersects the open segment (a,b).
		var other: Vector2 = d if _are_close(c, excl) else c
		return _seg_contains_point(a, b, other)
	return _seg_seg_intersects(a, b, c, d)

func _seg_contains_point(a: Vector2, b: Vector2, p: Vector2) -> bool:
	# p lies on open segment (a,b) if collinear and within box.
	if abs(_ccw(a, b, p)) > 1e-9:
		return false
	return min(a.x, b.x) - 1e-9 < p.x and p.x < max(a.x, b.x) + 1e-9 and \
		   min(a.y, b.y) - 1e-9 < p.y and p.y < max(a.y, b.y) + 1e-9

func _hole_rotated_for_bridge(hole: PackedVector2Array, start_idx: int) -> PackedVector2Array:
	var rotated: PackedVector2Array = PackedVector2Array()
	for i in range(hole.size()):
		rotated.append(hole[(start_idx + i) % hole.size()])
	rotated.append(hole[start_idx]) # Close the hole.
	return rotated

func _are_adjacent(t0: PackedVector2Array, t1: PackedVector2Array, eps: float) -> bool:
	var match_count: int = 0
	for v0 in t0:
		for v1 in t1:
			if v0.distance_squared_to(v1) < eps * eps:
				match_count += 1
				break
	return match_count >= 2

func _signed_area2(a: Vector2, b: Vector2, c: Vector2) -> float:
	return (b.x - a.x) * (c.y - a.y) - (c.x - a.x) * (b.y - a.y)

func _to_ccw(p: PackedVector2Array) -> PackedVector2Array:
	if Geometry2D.is_polygon_clockwise(p):
		var cp: PackedVector2Array = PackedVector2Array(p)
		cp.reverse()
		return cp
	return p

func _to_cw(p: PackedVector2Array) -> PackedVector2Array:
	if not Geometry2D.is_polygon_clockwise(p):
		var cp: PackedVector2Array = PackedVector2Array(p)
		cp.reverse()
		return cp
	return p

func _ccw(a: Vector2, b: Vector2, c: Vector2) -> float:
	return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x)

func _are_close(a: Vector2, b: Vector2) -> bool:
	return a.distance_squared_to(b) < 1e-12

func _approx_eq(a: Vector2, b: Vector2, tol: float) -> bool:
	return abs(a.x - b.x) < tol and abs(a.y - b.y) < tol

func _snap(p: Vector2) -> Vector2:
	var s: float = 0.5
	return Vector2(snappedf(p.x, s), snappedf(p.y, s))

