func _count_components(adj):
  var vis={}
  var comps=0
  for i in range(adj.size()):
    if not vis.has(i):
      comps+=1
      var q=[i]; vis[i]=true
      while q.size()>0:
        var u=q.pop_back()
        for v in adj[u]:
          if not vis.has(v): vis[v]=true; q.push_back(v)
  return comps
